import { useMemo, useState } from 'react'

import { ALL_SEMESTER_FILTER_VALUE } from 'src/data/semesterFilter'

import { type Semester } from 'src/models/date'
import { type ClubReview } from 'src/responses/review'

type SemesterFilterOption = `${number}-${Semester}`

export type SemesterFilterValue = typeof ALL_SEMESTER_FILTER_VALUE | SemesterFilterOption

const getSemesterFilterOption = ({ year, semester }: Pick<ClubReview, 'year' | 'semester'>): SemesterFilterOption =>
  `${year}-${semester}`

export const formatSemesterFilterOptionLabel = (semesterFilterOption: SemesterFilterOption): string => {
  const [year, semester] = semesterFilterOption.split('-')
  return `${year}-${semester === 'SPRING' ? '1' : '2'}`
}

export const useSemesterFilteredReviews = (reviews?: ClubReview[]) => {
  const [selectedSemesterFilterValue, setSelectedSemesterFilterValue] =
    useState<SemesterFilterValue>(ALL_SEMESTER_FILTER_VALUE)

  const semesterFilterOptions = useMemo(() => {
    if (!reviews) return []

    const semesterFilterOptionSet = new Set(reviews.map(getSemesterFilterOption))
    return Array.from(semesterFilterOptionSet).sort((a, b) => b.localeCompare(a))
  }, [reviews])

  const semesterFilteredReviews = useMemo(() => {
    if (!reviews) return []
    if (selectedSemesterFilterValue === ALL_SEMESTER_FILTER_VALUE) return reviews

    return reviews.filter(review => getSemesterFilterOption(review) === selectedSemesterFilterValue)
  }, [reviews, selectedSemesterFilterValue])

  return {
    selectedSemesterFilterValue,
    setSelectedSemesterFilterValue,
    semesterFilterOptions,
    semesterFilteredReviews
  }
}
